rollback.sql:
DO $$ BEGIN
                IF EXISTS (SELECT 1 FROM attachment WHERE owner_kind = 'HOUSEHOLD') THEN
                    RAISE EXCEPTION 'Household inspection photos are stored as attachments; move them back before rolling back';
                END IF;
                ALTER TABLE attachment DROP CONSTRAINT attachment_owner_kind_check;
                ALTER TABLE attachment ADD CONSTRAINT attachment_owner_kind_check CHECK (owner_kind IN ('RESIDENT','FACILITY','GUIDANCE'));
            END $$;
